// Collisions and picking.
//
// Collisions: entities get a type (EntityType), and Collisions says which types collide with which, and what
// happens then. UpdateWorld moves every entity that can collide from where it was at the last UpdateWorld to where
// the program put it, and stops or slides it when it hits something on the way. Entities that collide are
// ellipsoids (EntityRadius), what they collide with can be spheres, the polygons of a mesh, or boxes.
//
// This is done with the swept ellipsoid method: the world is squashed so that the ellipsoid becomes a unit sphere,
// then a sphere is moved along a line and tested against triangles.
//
// Picking: finds what is along a line or a ray, for entities that have a pick mode.

#include "profile.hpp"
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "scene.hpp"

extern "C" {
void bb_runtime_error(const char* message);
void bb_animation_update(float speed);
}

namespace {
	using namespace bb;

	struct vec3 {
		float x = 0, y = 0, z = 0;
	};

	vec3  operator+(vec3 a, vec3 b) { return { a.x + b.x, a.y + b.y, a.z + b.z }; }
	vec3  operator-(vec3 a, vec3 b) { return { a.x - b.x, a.y - b.y, a.z - b.z }; }
	vec3  operator*(vec3 a, float s) { return { a.x * s, a.y * s, a.z * s }; }
	float dot(vec3 a, vec3 b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
	vec3  cross(vec3 a, vec3 b) { return { a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x }; }
	float length_squared(vec3 a) { return dot(a, a); }
	float length(vec3 a) { return sqrtf(dot(a, a)); }
	vec3  normalized(vec3 a)
	{
		float l = length(a);
		return l > 1e-12f ? a * (1.0f / l) : vec3();
	}

	vec3 transform(const float* m, vec3 p)
	{
		return { m[0] * p.x + m[4] * p.y + m[8] * p.z + m[12], m[1] * p.x + m[5] * p.y + m[9] * p.z + m[13], m[2] * p.x + m[6] * p.y + m[10] * p.z + m[14] };
	}

	vec3 divided(vec3 a, vec3 r) { return { a.x / r.x, a.y / r.y, a.z / r.z }; }
	vec3 multiplied(vec3 a, vec3 r) { return { a.x * r.x, a.y * r.y, a.z * r.z }; }

	struct triangle {
		vec3 a, b, c;
		int  surface;
		int  index;
	};

	////////////////////////////////////////////////////////////////////////////
	// What the program asked for
	////////////////////////////////////////////////////////////////////////////
	struct rule {
		int source, destination, method, response;
	};
	buffer<rule> rules;

	struct contact {
		int   entity;
		vec3  point, normal;
		float time;
		int   surface, triangle;
	};

	struct contact_list {
		buffer<contact> contacts;
	};
	buffer<contact_list> contact_lists; // Indexed by entity handle - 1.

	contact_list& contacts_of(int handle)
	{
		while (contact_lists.size < uint32_t(handle)) {
			contact_lists.push(contact_list());
		}
		return contact_lists[uint32_t(handle) - 1];
	}

	[[noreturn]] void fail(const char* what)
	{
		bb_runtime_error(what);
		exit(1);
	}

	entity* need(int handle, const char* what)
	{
		entity* e = get_entity(handle);
		if (!e) {
			char message[96];
			snprintf(message, sizeof(message), "%s: the entity does not exist.", what);
			fail(message);
		}
		return e;
	}

	////////////////////////////////////////////////////////////////////////////
	// Triangles of entities
	////////////////////////////////////////////////////////////////////////////
	struct box3 {
		vec3 lo, hi;
		bool empty = true;

		void add(vec3 p)
		{
			if (empty) {
				lo = hi = p;
				empty   = false;
				return;
			}
			lo = { fminf(lo.x, p.x), fminf(lo.y, p.y), fminf(lo.z, p.z) };
			hi = { fmaxf(hi.x, p.x), fmaxf(hi.y, p.y), fmaxf(hi.z, p.z) };
		}

		bool overlaps(box3 const& o) const
		{
			return !empty && !o.empty && (lo.x <= o.hi.x) && (hi.x >= o.lo.x) && (lo.y <= o.hi.y) && (hi.y >= o.lo.y) && (lo.z <= o.hi.z) && (hi.z >= o.lo.z);
		}
	};

	// Box that is the mesh of the entity before it is moved. Boxes set with EntityBox are used when there is one.
	box3 local_bounds(entity const& e)
	{
		box3 box;
		if (e.has_box) {
			box.add({ e.box[0], e.box[1], e.box[2] });
			box.add({ e.box[0] + e.box[3], e.box[1] + e.box[4], e.box[2] + e.box[5] });
			return box;
		}
		for (uint32_t i = 0; i < e.surfaces.size; i++) {
			for (uint32_t v = 0; v < e.surfaces[i]->vertices.size; v++) {
				vertex3d const& vert = e.surfaces[i]->vertices[v];
				box.add({ vert.x, vert.y, vert.z });
			}
		}
		return box;
	}

	// Box that is around the entity in the world.
	box3 world_bounds(entity const& e, const float* m)
	{
		box3 local = local_bounds(e), result;
		if (local.empty) {
			return result;
		}
		for (int corner = 0; corner < 8; corner++) {
			result.add(transform(m, { (corner & 1) ? local.hi.x : local.lo.x, (corner & 2) ? local.hi.y : local.lo.y, (corner & 4) ? local.hi.z : local.lo.z }));
		}
		return result;
	}

	// Calls the function for the triangles of the entity that are in the world box, in world coordinates.
	template<typename F>
	void each_triangle_matrix(entity& e, const float* m, box3 const& area, F&& visit)
	{

		if (e.terrain) {
			// Terrains have too many triangles to look at all of them, so only the cells in the area are looked at.
			update_terrain(e);
			float inverse[16];
			mat_affine_inverse(m, inverse);
			box3 local;
			for (int corner = 0; corner < 8; corner++) {
				local.add(transform(inverse, { (corner & 1) ? area.hi.x : area.lo.x, (corner & 2) ? area.hi.y : area.lo.y, (corner & 4) ? area.hi.z : area.lo.z }));
			}
			int n  = e.terrain->size;
			int x0 = int(floorf(local.lo.x)) - 1, x1 = int(ceilf(local.hi.x)) + 1;
			int z0 = int(floorf(local.lo.z)) - 1, z1 = int(ceilf(local.hi.z)) + 1;
			x0 = x0 < 0 ? 0 : x0;
			z0 = z0 < 0 ? 0 : z0;
			x1 = x1 > n - 1 ? n - 1 : x1;
			z1 = z1 > n - 1 ? n - 1 : z1;
			const float* h = e.terrain->heights;
			for (int z = z0; z <= z1; z++) {
				for (int x = x0; x <= x1; x++) {
					vec3 p00 = transform(m, { float(x), h[z * (n + 1) + x], float(z) });
					vec3 p10 = transform(m, { float(x + 1), h[z * (n + 1) + x + 1], float(z) });
					vec3 p01 = transform(m, { float(x), h[(z + 1) * (n + 1) + x], float(z + 1) });
					vec3 p11 = transform(m, { float(x + 1), h[(z + 1) * (n + 1) + x + 1], float(z + 1) });
					// Same winding as the mesh: clockwise seen from above.
					visit(triangle{ p00, p01, p10, 0, (z * n + x) * 2 });
					visit(triangle{ p10, p01, p11, 0, (z * n + x) * 2 + 1 });
				}
			}
			return;
		}

		for (uint32_t s = 0; s < e.surfaces.size; s++) {
			surface& surf = *e.surfaces[s];
			for (uint32_t i = 0; i + 2 < surf.indices.size; i += 3) {
				vertex3d const &a = surf.vertices[surf.indices[i]], &b = surf.vertices[surf.indices[i + 1]], &c = surf.vertices[surf.indices[i + 2]];
				triangle t = { transform(m, { a.x, a.y, a.z }), transform(m, { b.x, b.y, b.z }), transform(m, { c.x, c.y, c.z }), int(s) + 1, int(i / 3) };
				box3 tb;
				tb.add(t.a);
				tb.add(t.b);
				tb.add(t.c);
				if (tb.overlaps(area)) {
					visit(t);
				}
			}
		}
	}

	template<typename F>
	void each_triangle(int handle, entity& e, box3 const& area, F&& visit)
	{
		float m[16];
		world_matrix(handle, m);
		each_triangle_matrix(e, m, area, visit);
	}

	// The 12 triangles of a box, in world coordinates.
	template<typename F>
	void each_box_triangle(entity const& e, const float* m, F&& visit)
	{
		box3 local = local_bounds(e);
		if (local.empty) {
			return;
		}
		vec3 c[8];
		for (int i = 0; i < 8; i++) {
			c[i] = transform(m, { (i & 1) ? local.hi.x : local.lo.x, (i & 2) ? local.hi.y : local.lo.y, (i & 4) ? local.hi.z : local.lo.z });
		}
		static const int faces[12][3] = {
			{ 0, 2, 1 }, { 1, 2, 3 }, { 4, 5, 6 }, { 5, 7, 6 }, { 0, 1, 4 }, { 1, 5, 4 }, { 2, 6, 3 }, { 3, 6, 7 }, { 0, 4, 2 }, { 2, 4, 6 }, { 1, 3, 5 }, { 3, 7, 5 },
		};
		for (int i = 0; i < 12; i++) {
			// Both sides count, so that it does not matter which way the box was turned by a negative scale.
			visit(triangle{ c[faces[i][0]], c[faces[i][1]], c[faces[i][2]], 0, i });
			visit(triangle{ c[faces[i][0]], c[faces[i][2]], c[faces[i][1]], 0, i });
		}
	}

	////////////////////////////////////////////////////////////////////////////
	// Moving a sphere along a line, and finding what it hits. This is how the original does it: the sphere is a point
	// that moves along a line, and what it hits is made bigger by the radius of the sphere instead.
	////////////////////////////////////////////////////////////////////////////
	const float collision_epsilon = 0.001f;

	struct line3 {
		vec3 o, d;
	};

	vec3 at(line3 const& l, float t) { return l.o + l.d * t; }

	struct plane3 {
		vec3  n;
		float d = 0;

		float distance(vec3 p) const { return dot(n, p) + d; }
		float t_intersect(line3 const& l) const { return -distance(l.o) / dot(n, l.d); }
		vec3  nearest(vec3 q) const { return q - n * distance(q); }
	};

	plane3 plane_through(vec3 point, vec3 normal) { return { normal, -dot(normal, point) }; }

	plane3 plane_of(vec3 v0, vec3 v1, vec3 v2)
	{
		vec3 n = normalized(cross(v1 - v0, v2 - v0));
		return { n, -dot(n, v0) };
	}

	// Where two planes meet.
	line3 plane_meeting(plane3 const& a, plane3 const& b)
	{
		vec3   lv        = normalized(cross(a.n, b.n));
		line3  across    = { a.nearest(a.n * -a.d), cross(a.n, lv) };
		vec3   on_b      = at(across, b.t_intersect(across));
		return { on_b, lv };
	}

	vec3 nearest_on_line(line3 const& l, vec3 q) { return l.o + l.d * (dot(l.d, q - l.o) / dot(l.d, l.d)); }

	// What the closest hit so far is, in the same units as the line.
	struct hit_info {
		float time = 1;
		vec3  normal;
		int   surface = 0, triangle = 0;
	};

	bool hit_update(hit_info& c, line3 const& line, float t, vec3 n)
	{
		if (t > c.time) {
			return false;
		}
		plane3 p = plane_through(at(line, t), n);
		if (dot(p.n, line.d) >= 0) {
			return false;
		}
		if (p.distance(line.o) < -collision_epsilon) {
			return false;
		}
		c.time   = t;
		c.normal = n;
		return true;
	}

	bool hit_sphere(hit_info& c, line3 const& line, float radius, vec3 dest, float dest_radius)
	{
		radius += dest_radius;
		line3 l = { line.o - dest, line.d };
		float a = dot(l.d, l.d);
		if (a == 0) {
			return false;
		}
		float b = dot(l.o, l.d) * 2;
		float cc = dot(l.o, l.o) - radius * radius;
		float d  = b * b - 4 * a * cc;
		if (d < 0) {
			return false;
		}
		float t1 = (-b + sqrtf(d)) / (2 * a), t2 = (-b - sqrtf(d)) / (2 * a);
		float t = t1 < t2 ? t1 : t2;
		if (t > c.time) {
			return false;
		}
		return hit_update(c, line, t, normalized(at(l, t)));
	}

	// v0, v1: the ends of the edge, pn: normal of the polygon, en: normal of the plane of the edge.
	bool hit_edge(hit_info& c, vec3 v0, vec3 v1, vec3 pn, vec3 en, line3 const& line, float radius)
	{
		vec3 axis_j = normalized(v1 - v0);
		// The matrix with en, the direction of the edge and pn as its columns, which turns what is in the world into
		// what is around the edge.
		auto to_edge   = [&](vec3 p) { return vec3{ dot(en, p), dot(axis_j, p), dot(pn, p) }; };
		auto from_edge = [&](vec3 p) { return en * p.x + axis_j * p.y + pn * p.z; };

		vec3  sv = to_edge(line.o - v0), dv = to_edge(line.o + line.d - v0);
		line3 l  = { sv, dv - sv };
		// The cylinder around the edge...
		float a = l.d.x * l.d.x + l.d.z * l.d.z;
		if (a == 0) {
			return false;
		}
		float b = (l.o.x * l.d.x + l.o.z * l.d.z) * 2;
		float cc = (l.o.x * l.o.x + l.o.z * l.o.z) - radius * radius;
		float d  = b * b - 4 * a * cc;
		if (d < 0) {
			return false;
		}
		float t1 = (-b + sqrtf(d)) / (2 * a), t2 = (-b - sqrtf(d)) / (2 * a);
		float t = t1 < t2 ? t1 : t2;
		if (t > c.time) {
			return false;
		}
		vec3 i = at(l, t), p;
		if (i.y > length(v1 - v0)) {
			return false; // Above the cylinder.
		}
		if (i.y >= 0) {
			p.y = i.y;
		} else {
			// ...and the sphere around the end of it.
			a = dot(l.d, l.d);
			if (a == 0) {
				return false;
			}
			b  = dot(l.o, l.d) * 2;
			cc = dot(l.o, l.o) - radius * radius;
			d  = b * b - 4 * a * cc;
			if (d < 0) {
				return false;
			}
			t1 = (-b + sqrtf(d)) / (2 * a);
			t2 = (-b - sqrtf(d)) / (2 * a);
			t  = t1 < t2 ? t1 : t2;
			if (t > c.time) {
				return false;
			}
			i = at(l, t);
		}
		return hit_update(c, line, t, normalized(from_edge(i - p)));
	}

	bool hit_triangle(hit_info& c, line3 const& line, float radius, vec3 v0, vec3 v1, vec3 v2)
	{
		plane3 p = plane_of(v0, v1, v2);
		if (dot(p.n, line.d) >= 0) {
			return false;
		}
		p.d -= radius; // The plane, moved out by the radius.
		float t = p.t_intersect(line);
		if (t > c.time) {
			return false;
		}
		plane3 p0 = plane_of(v0 + p.n, v1, v0), p1 = plane_of(v1 + p.n, v2, v1), p2 = plane_of(v2 + p.n, v0, v2);
		vec3   i = at(line, t);
		if ((p0.distance(i) >= 0) && (p1.distance(i) >= 0) && (p2.distance(i) >= 0)) {
			return hit_update(c, line, t, p.n);
		}
		if (radius <= 0) {
			return false;
		}
		bool hit = hit_edge(c, v0, v1, p.n, p0.n, line, radius);
		hit |= hit_edge(c, v1, v2, p.n, p1.n, line, radius);
		hit |= hit_edge(c, v2, v0, p.n, p2.n, line, radius);
		return hit;
	}

	bool hit_box(hit_info& c, line3 const& line, float radius, vec3 const* corners)
	{
		static const int quads[] = { 2, 3, 1, 0, 3, 7, 5, 1, 7, 6, 4, 5, 6, 2, 0, 4, 6, 7, 3, 2, 0, 1, 5, 4 };
		bool             hit     = false;
		for (int n = 0; n < 24; n += 4) {
			vec3   v0 = corners[quads[n]], v1 = corners[quads[n + 1]], v2 = corners[quads[n + 2]], v3 = corners[quads[n + 3]];
			plane3 p = plane_of(v0, v1, v2);
			if (dot(p.n, line.d) >= 0) {
				continue;
			}
			p.d -= radius;
			float t = p.t_intersect(line);
			if (t > c.time) {
				return false;
			}
			plane3 p0 = plane_of(v0 + p.n, v1, v0), p1 = plane_of(v1 + p.n, v2, v1), p2 = plane_of(v2 + p.n, v3, v2), p3 = plane_of(v3 + p.n, v0, v3);
			vec3   i = at(line, t);
			if ((p0.distance(i) >= 0) && (p1.distance(i) >= 0) && (p2.distance(i) >= 0) && (p3.distance(i) >= 0)) {
				hit |= hit_update(c, line, t, p.n);
				continue;
			}
			if (radius <= 0) {
				continue;
			}
			hit |= hit_edge(c, v0, v1, p.n, p0.n, line, radius);
			hit |= hit_edge(c, v1, v2, p.n, p1.n, line, radius);
			hit |= hit_edge(c, v2, v3, p.n, p2.n, line, radius);
			hit |= hit_edge(c, v3, v0, p.n, p3.n, line, radius);
		}
		return hit;
	}

	// The smallest root of a x^2 + b x + c that is less than the limit.
	bool lowest_root(float a, float b, float c, float limit, float& out)
	{
		float determinant = b * b - 4 * a * c;
		if ((determinant < 0) || (fabsf(a) < 1e-20f)) {
			return false;
		}
		float root = sqrtf(determinant);
		float r1 = (-b - root) / (2 * a), r2 = (-b + root) / (2 * a);
		if (r1 > r2) {
			float t = r1;
			r1      = r2;
			r2      = t;
		}
		if ((r1 > 0) && (r1 < limit)) {
			out = r1;
			return true;
		}
		if ((r2 > 0) && (r2 < limit)) {
			out = r2;
			return true;
		}
		return false;
	}

	////////////////////////////////////////////////////////////////////////////
	// Moving entities
	////////////////////////////////////////////////////////////////////////////
	// Whether it and everything that it is below is shown, because hiding something turns off what it can collide with.
	bool is_enabled(int handle)
	{
		for (int h = handle; h; ) {
			entity* e = get_entity(h);
			if (!e || e->hidden) {
				return false;
			}
			h = e->parent;
		}
		return true;
	}

	// The radii that the original uses: the one for the width is also the one for the depth.
	vec3 radii_of(entity const& e) { return { e.radius[0], e.radius[1] > 0 ? e.radius[1] : e.radius[0], e.radius[0] }; }

	// Everything that can be collided with, by type.
	buffer<int> by_type[1000];

	bool is_source(int type)
	{
		for (uint32_t r = 0; r < rules.size; r++) {
			if (rules[r].source == type) {
				return true;
			}
		}
		return false;
	}

	// Sets where an entity is in the world, without changing anything else.
	void put_in_world(int handle, entity& e, vec3 world)
	{
		(void)handle;
		if (e.parent) {
			float m[16], inverse[16];
			world_matrix(e.parent, m);
			mat_affine_inverse(m, inverse);
			vec3 local    = transform(inverse, world);
			e.position[0] = local.x;
			e.position[1] = local.y;
			e.position[2] = local.z;
		} else {
			e.position[0] = world.x;
			e.position[1] = world.y;
			e.position[2] = world.z;
		}
	}

	// The box that is collided with: the one that was set, or one of two by two by two around the middle.
	box3 collision_box(entity const& e)
	{
		box3 box;
		if (e.has_box) {
			box.add({ e.box[0], e.box[1], e.box[2] });
			box.add({ e.box[0] + e.box[3], e.box[1] + e.box[4], e.box[2] + e.box[5] });
		} else {
			box.add({ -1, -1, -1 });
			box.add({ 1, 1, 1 });
		}
		return box;
	}

	// Tests one entity that is collided with.
	bool hit_entity(hit_info& c, line3 const& line, float radius, entity& e, const float* tform, int method)
	{
		switch (method) {
		case 1:
			return hit_sphere(c, line, radius, { tform[12], tform[13], tform[14] }, e.radius[0]);
		case 2: {
			box3 area;
			area.add(line.o);
			area.add(line.o + line.d);
			area.lo = area.lo - vec3{ radius, radius, radius };
			area.hi = area.hi + vec3{ radius, radius, radius };
			bool hit = false;
			each_triangle_matrix(e, tform, area, [&](triangle const& t) {
				if (hit_triangle(c, line, radius, t.a, t.b, t.c)) {
					c.surface  = t.surface;
					c.triangle = t.index;
					hit        = true;
				}
			});
			return hit;
		}
		default: {
			// The box is in the space of the entity, with its axes one long so that the box is not stretched.
			float m[16];
			memcpy(m, tform, sizeof(m));
			for (int axis = 0; axis < 3; axis++) {
				vec3  col = { m[axis * 4], m[axis * 4 + 1], m[axis * 4 + 2] };
				float len = length(col);
				if (len > 1e-12f) {
					m[axis * 4] /= len;
					m[axis * 4 + 1] /= len;
					m[axis * 4 + 2] /= len;
				}
			}
			vec3  position = { m[12], m[13], m[14] };
			auto  inverse_rotate = [&](vec3 p) { return vec3{ m[0] * p.x + m[1] * p.y + m[2] * p.z, m[4] * p.x + m[5] * p.y + m[6] * p.z, m[8] * p.x + m[9] * p.y + m[10] * p.z }; };
			auto  rotate         = [&](vec3 p) { return vec3{ m[0] * p.x + m[4] * p.y + m[8] * p.z, m[1] * p.x + m[5] * p.y + m[9] * p.z, m[2] * p.x + m[6] * p.y + m[10] * p.z }; };
			line3 local          = { inverse_rotate(line.o - position), inverse_rotate(line.d) };
			box3  box            = collision_box(e);
			vec3  corners[8];
			for (int i = 0; i < 8; i++) {
				corners[i] = { (i & 1) ? box.hi.x : box.lo.x, (i & 2) ? box.hi.y : box.lo.y, (i & 4) ? box.hi.z : box.lo.z };
			}
			if (hit_box(c, local, radius, corners)) {
				c.normal = rotate(c.normal);
				return true;
			}
			return false;
		}
		}
	}

	// Moves one entity from where it was to where it is now, the way the original does it.
	void collide(int handle, entity& src)
	{
		float now_matrix[16];
		world_matrix(handle, now_matrix);
		vec3 dv = { now_matrix[12], now_matrix[13], now_matrix[14] };
		vec3 sv = { src.old_pos[0], src.old_pos[1], src.old_pos[2] };
		if ((sv.x == dv.x) && (sv.y == dv.y) && (sv.z == dv.z)) {
			return;
		}
		vec3 panic = sv;

		vec3  radii  = radii_of(src);
		float radius = radii.x, y_scale = 1, inv_y_scale = 1;
		if (radii.x != radii.y) {
			y_scale     = radius / radii.y;
			inv_y_scale = 1 / y_scale;
			sv.y *= y_scale;
			dv.y *= y_scale;
		}

		int      n_hit = 0;
		plane3   planes[2];
		line3    coll_line = { sv, dv - sv };
		vec3     dir       = coll_line.d;
		float    td        = length(coll_line.d);
		float    td_xz     = length({ coll_line.d.x, 0, coll_line.d.z });
		int      hits      = 0;
		const int max_hits = 10;

		for (;;) {
			hit_info coll;
			int      coll_object   = 0;
			int      coll_response = 0;
			for (uint32_t r = 0; r < rules.size; r++) {
				if (rules[r].source != src.coll_type) {
					continue;
				}
				buffer<int> const& objects = by_type[rules[r].destination];
				for (uint32_t k = 0; k < objects.size; k++) {
					int other = objects[k];
					if (other == handle) {
						continue;
					}
					entity* dst = get_entity(other);
					float   m[16];
					if (dst->old_valid) {
						memcpy(m, dst->old_matrix, sizeof(m)); // Where it was, as the original does.
					} else {
						world_matrix(other, m);
					}
					if (y_scale != 1) {
						m[1] *= y_scale;
						m[5] *= y_scale;
						m[9] *= y_scale;
						m[13] *= y_scale;
					}
					if (hit_entity(coll, coll_line, radius, *dst, m, rules[r].method)) {
						coll_object   = other;
						coll_response = rules[r].response;
					}
				}
			}
			if (!coll_object) {
				break;
			}
			if (++hits == max_hits) {
				break;
			}

			// What happened is told to both of them.
			{
				contact c;
				c.point    = at(coll_line, coll.time) - coll.normal * radii.x;
				c.point.y *= inv_y_scale;
				c.normal   = coll.normal;
				c.time     = coll.time;
				c.surface  = coll.surface;
				c.triangle = coll.triangle;
				c.entity   = coll_object;
				contacts_of(handle).contacts.push(c);
				c.entity = handle;
				contacts_of(coll_object).contacts.push(c);
			}

			plane3 coll_plane = plane_through(at(coll_line, coll.time), coll.normal);
			coll_plane.d -= collision_epsilon;
			coll.time = coll_plane.t_intersect(coll_line);
			if (coll.time > 0) {
				// Only moves forward.
				sv = at(coll_line, coll.time);
				td *= 1 - coll.time;
				td_xz *= 1 - coll.time;
			}

			if (coll_response == 1) {
				dv = sv;
				break;
			}

			// The nearest point on the plane to where it wanted to go.
			vec3 nv = coll_plane.nearest(dv);
			if (n_hit == 0) {
				dv = nv;
			} else if (n_hit == 1) {
				if (planes[0].distance(nv) >= 0) {
					dv    = nv;
					n_hit = 0;
				} else if (fabsf(dot(planes[0].n, coll_plane.n)) < 1 - 0.0001f) {
					dv = nearest_on_line(plane_meeting(coll_plane, planes[0]), dv);
				} else {
					hits = max_hits; // Squished.
					break;
				}
			} else if ((planes[0].distance(nv) >= 0) && (planes[1].distance(nv) >= 0)) {
				dv    = nv;
				n_hit = 0;
			} else {
				dv = sv;
				break;
			}

			vec3 dd = dv - sv;

			// Not going backwards.
			if (dot(dd, dir) <= 0) {
				dv = sv;
				break;
			}

			if (coll_response == 2) {
				float d = length(dd);
				if (d <= 0.0001f) {
					dv = sv;
					break;
				}
				if (d > td) {
					dd = dd * (td / d);
				}
			} else if (coll_response == 3) {
				float d = length({ dd.x, 0, dd.z });
				if (d <= 0.0001f) {
					dv = sv;
					break;
				}
				if (d > td_xz) {
					dd = dd * (td_xz / d);
				}
			}

			coll_line.o = sv;
			coll_line.d = dd;
			dv          = sv + dd;
			planes[n_hit++] = coll_plane;
		}

		if (hits) {
			if (hits < max_hits) {
				dv.y *= inv_y_scale;
				put_in_world(handle, src, dv);
			} else {
				put_in_world(handle, src, panic);
			}
		}
	}

	void update_collisions()
	{
		if (rules.size == 0) {
			return;
		}
		// What can be collided with, by type.
		for (int t = 0; t < 1000; t++) {
			by_type[t].clear();
		}
		bool is_destination[1000] = {};
		for (uint32_t r = 0; r < rules.size; r++) {
			is_destination[rules[r].destination] = true;
		}
		for (int handle = 1; handle <= entity_count(); handle++) {
			entity* e = get_entity(handle);
			if (e && (e->coll_type > 0) && (e->coll_type < 1000) && is_destination[e->coll_type] && is_enabled(handle)) {
				by_type[e->coll_type].push(handle);
			}
		}

		for (int handle = 1; handle <= entity_count(); handle++) {
			entity* e = get_entity(handle);
			if (!e || (e->coll_type == 0)) {
				continue;
			}
			if (handle <= int(contact_lists.size)) {
				contact_lists[uint32_t(handle) - 1].contacts.clear();
			}
			if (!is_enabled(handle)) {
				continue;
			}
			float m[16];
			world_matrix(handle, m);
			if (!e->old_valid) {
				// It was just made or reset: nothing to sweep from.
				memcpy(e->old_matrix, m, sizeof(m));
				e->old_pos[0] = m[12];
				e->old_pos[1] = m[13];
				e->old_pos[2] = m[14];
				e->old_valid  = true;
			}
			if (is_source(e->coll_type)) {
				collide(handle, *e);
				world_matrix(handle, m);
			}
			memcpy(e->old_matrix, m, sizeof(m));
			e->old_pos[0] = m[12];
			e->old_pos[1] = m[13];
			e->old_pos[2] = m[14];
		}
	}

	////////////////////////////////////////////////////////////////////////////
	// Picking
	////////////////////////////////////////////////////////////////////////////
	struct pick {
		int   entity = 0;
		vec3  point, normal;
		float time = 0;
		int   surface = 0, triangle = 0;
	};
	pick last_pick;

	// Ray against a triangle, with the length of the direction as the range. Returns the time in [0, 1].
	bool ray_triangle(vec3 origin, vec3 direction, vec3 a, vec3 b, vec3 c, float& t)
	{
		vec3  e1 = b - a, e2 = c - a, p = cross(direction, e2);
		float det = dot(e1, p);
		if (fabsf(det) < 1e-12f) {
			return false;
		}
		float inverse = 1.0f / det;
		vec3  from    = origin - a;
		float u       = dot(from, p) * inverse;
		if ((u < 0) || (u > 1)) {
			return false;
		}
		vec3  q = cross(from, e1);
		float v = dot(direction, q) * inverse;
		if ((v < 0) || (u + v > 1)) {
			return false;
		}
		t = dot(e2, q) * inverse;
		return (t >= 0) && (t <= 1);
	}

	// Ray (or sphere with a radius) against a sphere. Time in [0, 1].
	bool ray_sphere(vec3 origin, vec3 direction, vec3 center, float radius, float& t)
	{
		vec3  d = origin - center;
		float a = dot(direction, direction), b = 2 * dot(direction, d), c = dot(d, d) - radius * radius, root;
		if (c <= 0) {
			t = 0;
			return true;
		}
		if (!lowest_root(a, b, c, 1.0f + 1e-6f, root)) {
			return false;
		}
		t = root;
		return true;
	}

	// Finds what is first along the line. If only_obscuring, what can not be seen through is the only thing that counts.
	pick find_pick(vec3 origin, vec3 direction, float radius, int ignore, int ignore2, bool only_obscuring)
	{
		pick best;
		best.entity  = 0;
		best.time    = 2;
		box3 area;
		area.add(origin - vec3{ radius, radius, radius });
		area.add(origin + direction + vec3{ radius, radius, radius });
		area.add(origin + vec3{ radius, radius, radius });
		area.add(origin + direction - vec3{ radius, radius, radius });

		for (int handle = 1; handle <= entity_count(); handle++) {
			entity* e = get_entity(handle);
			if (!e || (handle == ignore) || (handle == ignore2) || (e->pick_mode == 0) || e->hidden) {
				continue;
			}
			if (only_obscuring && !e->pick_obscure) {
				continue;
			}
			float m[16];
			world_matrix(handle, m);

			if (e->pick_mode == 1) {
				float rd = e->radius[0];
				if (rd <= 0) {
					continue;
				}
				float t;
				if (ray_sphere(origin, direction, { m[12], m[13], m[14] }, rd + radius, t) && (t < best.time)) {
					vec3 at   = origin + direction * t;
					best      = { handle, at, normalized(at - vec3{ m[12], m[13], m[14] }), t, 0, 0 };
				}
				continue;
			}

			auto test = [&](triangle const& tri) {
				float t;
				if (ray_triangle(origin, direction, tri.a, tri.b, tri.c, t) && (t < best.time)) {
					vec3 n = normalized(cross(tri.b - tri.a, tri.c - tri.a));
					if (dot(n, direction) > 0) {
						n = n * -1.0f; // The side that the ray comes from.
					}
					best = { handle, origin + direction * t, n, t, tri.surface, tri.index };
				}
			};
			if (e->pick_mode == 3) {
				each_box_triangle(*e, m, test);
			} else {
				box3 wb = world_bounds(*e, m);
				if (e->terrain) {
					wb = area;
				}
				if (!wb.overlaps(area)) {
					continue;
				}
				each_triangle(handle, *e, area, test);
			}
		}
		return best;
	}

	int set_pick(pick const& p)
	{
		if ((p.entity == 0) || (p.time > 1)) {
			// Like the original, a miss only says that nothing was hit, and that it took the whole line.
			last_pick.entity = 0;
			last_pick.time   = 1;
			return 0;
		}
		last_pick = p;
		return p.entity;
	}
} // namespace

////////////////////////////////////////////////////////////////////////////////
// For the camera, which knows about the screen
////////////////////////////////////////////////////////////////////////////////
extern "C" {
int32_t bb_line_pick(float x, float y, float z, float dx, float dy, float dz, float radius);

// UpdateWorld: collisions, and what is animated.
void bb_update_world(float speed)
{
	{
		bb::profile_scope timer(bb::PROFILE_ANIMATION);
		bb_animation_update(speed);
	}
	bb::profile_scope timer(bb::PROFILE_UPDATE_WORLD);
	update_collisions();
}

// ResetEntity: forgets where it was, so that the way to where it is now is not collided with.
void bb_reset_entity(int32_t handle)
{
	need(handle, "ResetEntity");
	reset_movement(handle);
	if (handle <= int(contact_lists.size)) {
		contact_lists[uint32_t(handle) - 1].contacts.clear();
	}
}

void bb_entity_type(int32_t handle, int32_t type, int32_t recursive)
{
	entity* e = need(handle, "EntityType");
	if ((type < 0) || (type > 999)) {
		fail("EntityType: the type has to be between 0 and 999.");
	}
	e->coll_type = type;
	reset_movement(handle);
	if (recursive) {
		for (int other = 1; other <= entity_count(); other++) {
			entity* child = get_entity(other);
			if (child && (child->parent == handle)) {
				bb_entity_type(other, type, 1);
			}
		}
	}
}

void bb_entity_radius(int32_t handle, float x_radius, float y_radius)
{
	entity* e = need(handle, "EntityRadius");
	e->radius[0] = x_radius;
	e->radius[1] = y_radius > 0 ? y_radius : x_radius;
}

void bb_entity_box(int32_t handle, float x, float y, float z, float w, float h, float d)
{
	entity* e = need(handle, "EntityBox");
	e->has_box = true;
	e->box[0] = x;
	e->box[1] = y;
	e->box[2] = z;
	e->box[3] = w;
	e->box[4] = h;
	e->box[5] = d;
}

void bb_entity_pick_mode(int32_t handle, int32_t mode, int32_t obscurer)
{
	entity* e = need(handle, "EntityPickMode");
	if ((mode < 0) || (mode > 3)) {
		fail("EntityPickMode: the mode has to be between 0 and 3.");
	}
	e->pick_mode    = mode;
	e->pick_obscure = obscurer != 0;
}

// Collisions between type, and what it can hit. Method: 1 = sphere, 2 = polygons, 3 = box.
// Response: 1 = stop, 2 = slide, 3 = slide, but not down slopes.
void bb_collisions(int32_t source, int32_t destination, int32_t method, int32_t response)
{
	if ((source < 0) || (source > 999) || (destination < 0) || (destination > 999)) {
		fail("Collisions: the types have to be between 0 and 999.");
	}
	if ((method < 1) || (method > 3) || (response < 1) || (response > 3)) {
		fail("Collisions: the method and the response have to be between 1 and 3.");
	}
	for (uint32_t r = 0; r < rules.size; r++) {
		if ((rules[r].source == source) && (rules[r].destination == destination)) {
			return; // A pair of types has one rule, the first one, until ClearCollisions.
		}
	}
	rules.push({ source, destination, method, response });
}

void bb_clear_collisions(void)
{
	rules.clear();
}

int32_t bb_count_collisions(int32_t handle)
{
	need(handle, "CountCollisions");
	return (handle <= int32_t(contact_lists.size)) ? int32_t(contact_lists[uint32_t(handle) - 1].contacts.size) : 0;
}

static contact const& contact_at(int32_t handle, int32_t index, const char* what)
{
	need(handle, what);
	if ((handle > int32_t(contact_lists.size)) || (index < 1) || (uint32_t(index) > contact_lists[uint32_t(handle) - 1].contacts.size)) {
		fail("There is no such collision.");
	}
	return contact_lists[uint32_t(handle) - 1].contacts[uint32_t(index) - 1];
}

int32_t bb_collision_entity(int32_t handle, int32_t index) { return contact_at(handle, index, "CollisionEntity").entity; }
float   bb_collision_x(int32_t handle, int32_t index) { return contact_at(handle, index, "CollisionX").point.x; }
float   bb_collision_y(int32_t handle, int32_t index) { return contact_at(handle, index, "CollisionY").point.y; }
float   bb_collision_z(int32_t handle, int32_t index) { return contact_at(handle, index, "CollisionZ").point.z; }
float   bb_collision_nx(int32_t handle, int32_t index) { return contact_at(handle, index, "CollisionNX").normal.x; }
float   bb_collision_ny(int32_t handle, int32_t index) { return contact_at(handle, index, "CollisionNY").normal.y; }
float   bb_collision_nz(int32_t handle, int32_t index) { return contact_at(handle, index, "CollisionNZ").normal.z; }
float   bb_collision_time(int32_t handle, int32_t index) { return contact_at(handle, index, "CollisionTime").time; }
int32_t bb_collision_surface(int32_t handle, int32_t index) { return contact_at(handle, index, "CollisionSurface").surface; }
int32_t bb_collision_triangle(int32_t handle, int32_t index) { return contact_at(handle, index, "CollisionTriangle").triangle; }

// The entity of the given type that this one collided with, or 0.
int32_t bb_entity_collided(int32_t handle, int32_t type)
{
	need(handle, "EntityCollided");
	if (handle > int32_t(contact_lists.size)) {
		return 0;
	}
	buffer<contact>& list = contact_lists[uint32_t(handle) - 1].contacts;
	for (uint32_t i = 0; i < list.size; i++) {
		entity* other = get_entity(list[i].entity);
		if (other && (other->coll_type == type)) {
			return list[i].entity;
		}
	}
	return 0;
}

int32_t bb_line_pick(float x, float y, float z, float dx, float dy, float dz, float radius)
{
	return set_pick(find_pick({ x, y, z }, { dx, dy, dz }, radius, 0, 0, false));
}

// Looks along the Z axis of the entity, as far as the range.
int32_t bb_entity_pick(int32_t handle, float range)
{
	need(handle, "EntityPick");
	float m[16];
	world_matrix(handle, m);
	vec3 forward = { m[8], m[9], m[10] }; // Not made one long, so a scaled entity looks further.
	return set_pick(find_pick({ m[12], m[13], m[14] }, forward * range, 0, handle, 0, false));
}

// Is there a clear line between the two? Everything that can be picked and is not see-through is in the way.
int32_t bb_entity_visible(int32_t source, int32_t destination)
{
	need(source, "EntityVisible");
	need(destination, "EntityVisible");
	float a[16], b[16];
	world_matrix(source, a);
	world_matrix(destination, b);
	vec3 from = { a[12], a[13], a[14] }, to = { b[12], b[13], b[14] };
	pick p    = find_pick(from, to - from, 0, source, destination, true);
	return ((p.entity == 0) || (p.time > 1)) ? 1 : 0;
}

int32_t bb_picked_entity(void) { return last_pick.entity; }
float   bb_picked_x(void) { return last_pick.point.x; }
float   bb_picked_y(void) { return last_pick.point.y; }
float   bb_picked_z(void) { return last_pick.point.z; }
float   bb_picked_nx(void) { return last_pick.normal.x; }
float   bb_picked_ny(void) { return last_pick.normal.y; }
float   bb_picked_nz(void) { return last_pick.normal.z; }
float   bb_picked_time(void) { return last_pick.time; }
int32_t bb_picked_surface(void) { return last_pick.surface; }
int32_t bb_picked_triangle(void) { return last_pick.triangle; }

// Do the polygons of the two meshes touch?
int32_t bb_meshes_intersect(int32_t first, int32_t second)
{
	entity *a = need(first, "MeshesIntersect"), *b = need(second, "MeshesIntersect");
	float   ma[16], mb[16];
	world_matrix(first, ma);
	world_matrix(second, mb);
	box3 wa = world_bounds(*a, ma), wb = world_bounds(*b, mb);
	if (!wa.overlaps(wb)) {
		return 0;
	}
	box3 overlap;
	overlap.add({ fmaxf(wa.lo.x, wb.lo.x), fmaxf(wa.lo.y, wb.lo.y), fmaxf(wa.lo.z, wb.lo.z) });
	overlap.add({ fminf(wa.hi.x, wb.hi.x), fminf(wa.hi.y, wb.hi.y), fminf(wa.hi.z, wb.hi.z) });

	// Triangles of the second mesh that are in the overlap, tested against the edges of the first mesh's, and back.
	buffer<triangle> from_b;
	each_triangle(second, *b, overlap, [&](triangle const& t) { from_b.push(t); });
	bool hit = false;
	each_triangle(first, *a, overlap, [&](triangle const& t) {
		if (hit) {
			return;
		}
		vec3 edges[3][2] = { { t.a, t.b }, { t.b, t.c }, { t.c, t.a } };
		for (uint32_t i = 0; i < from_b.size && !hit; i++) {
			triangle const& u = from_b[i];
			float           time;
			for (auto& edge : edges) {
				if (ray_triangle(edge[0], edge[1] - edge[0], u.a, u.b, u.c, time)) {
					hit = true;
					return;
				}
			}
			vec3 other_edges[3][2] = { { u.a, u.b }, { u.b, u.c }, { u.c, u.a } };
			for (auto& edge : other_edges) {
				if (ray_triangle(edge[0], edge[1] - edge[0], t.a, t.b, t.c, time)) {
					hit = true;
					return;
				}
			}
		}
	});
	from_b.release();
	return hit ? 1 : 0;
}
}
